/**
 * Customer-audience OIDC tokens from the hosted pod identity socket.
 *
 * The platform sets the subject. Guest code only chooses the audience.
 */
import { existsSync } from "node:fs";
import { DEFAULT_CURSOR_AGENT_SOCKET, mintOidcOverSocket, OIDC_TOKEN_REFRESH_SKEW_MS, } from "./internal/cursor/cloud-agent-identity.js";
/** Backend mint budget is 15s. The socket itself closes at 30s. */
const MINT_TIMEOUT_MS = 20_000;
const NOT_HOSTED_CODES = new Set(["ENOENT", "ENOTSOCK", "ECONNREFUSED"]);
/** Failure from {@link getOidcToken}. `code` says which kind. */
export class OidcTokenError extends Error {
    constructor(input) {
        super(input.message);
        this.name = "OidcTokenError";
        this.code = input.code;
        this.status = input.status;
        this.reason = input.reason;
    }
}
/**
 * One cache of tokens, keyed by audience.
 * Callers share an in-flight mint for the same audience.
 */
export class OidcTokenClient {
    constructor(options = {}) {
        this.cache = new Map();
        this.inFlight = new Map();
        this.socketPath = options.socketPath;
        this.socketExists = options.socketExists ?? existsSync;
        this.now = options.now ?? Date.now;
        this.timeoutMs = options.timeoutMs ?? MINT_TIMEOUT_MS;
        this.mint = options.mint ?? mintOidcOverSocket;
    }
    get(audience) {
        const fresh = this.fresh(audience);
        if (fresh !== undefined) {
            return Promise.resolve(fresh);
        }
        if (!this.socketExists(this.resolveSocketPath())) {
            return Promise.reject(notHosted());
        }
        const pending = this.inFlight.get(audience);
        if (pending !== undefined) {
            return pending;
        }
        const flight = this.load(audience);
        this.inFlight.set(audience, flight);
        return flight;
    }
    fresh(audience) {
        const cached = this.cache.get(audience);
        if (cached === undefined) {
            return undefined;
        }
        if (cached.expiresAtMs - OIDC_TOKEN_REFRESH_SKEW_MS <= this.now()) {
            return undefined;
        }
        return toToken(cached);
    }
    load(audience) {
        return this.mint({
            socketPath: this.resolveSocketPath(),
            audience,
            timeoutMs: this.timeoutMs,
        })
            .then((result) => {
            if (result.kind !== "token") {
                throw errorFor(result);
            }
            const cached = { token: result.token, expiresAtMs: result.expiresAtMs };
            this.cache.set(audience, cached);
            return toToken(cached);
        })
            .finally(() => {
            this.inFlight.delete(audience);
        });
    }
    resolveSocketPath() {
        return this.socketPath ?? process.env.CURSOR_AGENT_SOCKET ?? DEFAULT_CURSOR_AGENT_SOCKET;
    }
}
/**
 * Mint an OIDC token for `audience` from the hosted pod.
 *
 * The platform sets the subject. It is `agent_sdk_deployment_id:` plus the
 * deployment public id (`asd_` and 32 hex characters). Pin that subject in
 * the relying party's trust policy. The issuer is `https://api.cursor.com`.
 *
 * The token is cached per audience and refreshed one minute before expiry.
 * Concurrent callers for one audience share one mint.
 *
 * Declare the audience on the agent, then exchange the token with the AWS SDK.
 * `fromWebToken` takes `webIdentityToken` as a string, so this calls STS and
 * passes the returned credentials to S3.
 *
 * ```ts
 * import { defineAgent, getOidcToken } from "@grok/agent-sdk";
 * import { ListObjectsV2Command, S3Client } from "@aws-sdk/client-s3";
 * import { AssumeRoleWithWebIdentityCommand, STSClient } from "@aws-sdk/client-sts";
 *
 * export default defineAgent({
 *   hosting: {
 *     oidc: { audiences: ["sts.amazonaws.com"] },
 *   },
 * });
 *
 * const { token } = await getOidcToken("sts.amazonaws.com");
 * const assumed = await new STSClient({ region: "us-west-2" }).send(
 *   new AssumeRoleWithWebIdentityCommand({
 *     RoleArn: "arn:aws:iam::123456789012:role/my-agent",
 *     RoleSessionName: "cursor-agent",
 *     WebIdentityToken: token,
 *   }),
 * );
 * const creds = assumed.Credentials;
 * if (
 *   creds?.AccessKeyId === undefined ||
 *   creds.SecretAccessKey === undefined ||
 *   creds.SessionToken === undefined
 * ) {
 *   throw new Error("STS did not return credentials");
 * }
 * const s3 = new S3Client({
 *   region: "us-west-2",
 *   credentials: {
 *     accessKeyId: creds.AccessKeyId,
 *     secretAccessKey: creds.SecretAccessKey,
 *     sessionToken: creds.SessionToken,
 *   },
 * });
 * await s3.send(new ListObjectsV2Command({ Bucket: "my-bucket" }));
 * ```
 *
 * Pin the deployment id in the role trust policy:
 *
 * ```json
 * {
 *   "StringEquals": {
 *     "api.cursor.com:aud": "sts.amazonaws.com",
 *     "api.cursor.com:sub": "agent_sdk_deployment_id:asd_3f9c0a7b1d2e4f60a9b8c7d6e5f40312"
 *   }
 * }
 * ```
 *
 * Throws {@link OidcTokenError}.
 */
export function getOidcToken(audience) {
    return sharedClient().get(audience);
}
let shared;
function sharedClient() {
    shared ??= new OidcTokenClient();
    return shared;
}
/** Drops the process cache. Tests use this so one case cannot feed the next. */
export function resetOidcTokenClientForTests() {
    shared = undefined;
}
function toToken(cached) {
    return { token: cached.token, expiresAt: new Date(cached.expiresAtMs) };
}
function notHosted() {
    return new OidcTokenError({
        code: "not_hosted",
        message: "OIDC mint requires a hosted pod. No identity socket is available.",
    });
}
function errorFor(result) {
    switch (result.kind) {
        case "timeout":
            return new OidcTokenError({ code: "timeout", message: "OIDC mint timed out" });
        case "malformed":
            return new OidcTokenError({
                code: "malformed",
                message: "OIDC mint returned a malformed response",
            });
        case "transport":
            if (result.code !== undefined && NOT_HOSTED_CODES.has(result.code)) {
                return notHosted();
            }
            return new OidcTokenError({
                code: "failed",
                message: "OIDC mint could not reach the identity socket",
            });
        case "http":
            return httpError(result.status, result.reason);
        default: {
            const _exhaustive = result;
            return _exhaustive;
        }
    }
}
function httpError(status, reason) {
    if (status === 403) {
        return new OidcTokenError({
            code: "refused",
            status,
            reason,
            message: reason === undefined ? "OIDC mint was refused" : `OIDC mint was refused: ${reason}`,
        });
    }
    if (status === 429) {
        return new OidcTokenError({
            code: "rate_limited",
            status,
            reason,
            message: reason === undefined
                ? "OIDC mint was rate limited"
                : `OIDC mint was rate limited: ${reason}`,
        });
    }
    return new OidcTokenError({
        code: "failed",
        status,
        reason,
        message: reason === undefined
            ? `OIDC mint failed with HTTP ${status}`
            : `OIDC mint failed with HTTP ${status}: ${reason}`,
    });
}
